// reanimate-flutter demo: widgets generated by css2flutter.ts from reanimate captures, shown live with their source.
//   mark_motion.dart  ← reanimate.niazmorshed.dev logo mark (@keyframes mark, infinite loop, phases)
//   rise_motion.dart  ← the local card test (@keyframes rise, 600 ms, 120 ms stagger, once)
import 'package:flutter/material.dart';

import 'demos/mark_demo.dart';
import 'demos/rise_demo.dart';
import 'source_view.dart';

void main() => runApp(const DemoApp());

class DemoApp extends StatelessWidget {
  const DemoApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'reanimate-flutter demo',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(colorSchemeSeed: const Color(0xFF4F46E5), useMaterial3: true),
      home: const DemoPage(),
    );
  }
}

class DemoPage extends StatelessWidget {
  const DemoPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF4F4F5),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 960),
            child: ListView(
              padding: const EdgeInsets.all(24),
              children: const [
                Text('reanimate-flutter demo', style: TextStyle(fontSize: 24, fontWeight: FontWeight.w600)),
                SizedBox(height: 6),
                Text(
                  'css2flutter.ts generated the *_motion.dart files from reanimate capture data (inspect.json). '
                  'The *_demo.dart files add the visuals and use them. Every file can be viewed, copied and downloaded.',
                  style: TextStyle(color: Color(0xFF52525B), height: 1.5),
                ),
                SizedBox(height: 24),
                _Panel(
                  title: '1 · Logo mark (infinite loop)',
                  caption: '@keyframes mark · 2.4 s · delays −240 / −120 / 0 ms · cubic-bezier(0.16, 1, 0.3, 1)',
                  demo: MarkDemo(),
                  files: [
                    SourceFile('lib/mark_motion.dart', 'generated'),
                    SourceFile('lib/demos/mark_demo.dart', 'usage'),
                  ],
                ),
                SizedBox(height: 20),
                _Panel(
                  title: '2 · Card stagger (once on load)',
                  caption: '@keyframes rise · 600 ms · 120 ms stagger · translateY(40px) → 0, opacity 0 → 1',
                  dark: true,
                  demo: RiseDemo(),
                  files: [
                    SourceFile('lib/rise_motion.dart', 'generated'),
                    SourceFile('lib/demos/rise_demo.dart', 'usage'),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _Panel extends StatelessWidget {
  const _Panel({required this.title, required this.caption, required this.demo, required this.files, this.dark = false});
  final String title, caption;
  final Widget demo;
  final List<SourceFile> files;
  final bool dark;

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: const Color(0x14000000)),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(24, 20, 24, 16),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(title, style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),
            const SizedBox(height: 4),
            Text(caption, style: const TextStyle(fontSize: 12, fontFamily: 'JetBrainsMono', color: Color(0xFF71717A))),
          ]),
        ),
        Container(
          color: dark ? const Color(0xFF0B0B0F) : const Color(0xFFFAFAFA),
          padding: const EdgeInsets.all(24),
          child: demo,
        ),
        Padding(padding: const EdgeInsets.all(16), child: SourceView(files: files)),
      ]),
    );
  }
}
